import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Locale;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;

        int n = Integer.parseInt(st.nextToken());
        double d = Double.parseDouble(st.nextToken());

        double[] p = new double[n + 1];
        double[] c = new double[n + 1];

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            p[i] = Double.parseDouble(st.nextToken());
            c[i] = Double.parseDouble(st.nextToken());
        }

        p[n] = d;

        double[] dp = new double[n + 1];
        Arrays.fill(dp, Double.POSITIVE_INFINITY);
        dp[0] = 0.0;

        for (int i = 0; i < n; i++) {
            double currentP = p[i];
            double currentC = c[i];
            double currentDp = dp[i];

            for (int j = i + 1; j <= n; j++) {
                double dist = p[j] - currentP;
                double time = (dist * dist) / currentC;
                if (currentDp + time < dp[j]) {
                    dp[j] = currentDp + time;
                }
            }
        }

        System.out.printf(Locale.US, "%.3f\n", dp[n]);
    }
}
